PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "crime_scene_report" (
	"date"	integer,
	"type"	text,
	"description"	text,
	"city"	text
);
CREATE TABLE IF NOT EXISTS "driver_license" (
	"id"	integer,
	"age"	integer,
	"height"	integer,
	"eye_color"	text,
	"hair_color"	text,
	"gender"	text,
	"plate_number"	text,
	"car_make"	text,
	"car_model"	text,
	PRIMARY KEY("id")
);
CREATE TABLE IF NOT EXISTS "facebook_event_checkin" (
	"person_id"	integer,
	"event_id"	integer,
	"event_name"	text,
	"date"	integer,
	FOREIGN KEY("person_id") REFERENCES "person"("id")
);
CREATE TABLE IF NOT EXISTS "interview" (
	"person_id"	integer,
	"transcript"	text,
	FOREIGN KEY("person_id") REFERENCES "person"("id")
);
CREATE TABLE IF NOT EXISTS "get_fit_now_member" (
	"id"	text,
	"person_id"	integer,
	"name"	text,
	"membership_start_date"	integer,
	"membership_status"	text,
	PRIMARY KEY("id"),
	FOREIGN KEY("person_id") REFERENCES "person"("id")
);
CREATE TABLE IF NOT EXISTS "get_fit_now_check_in" (
	"membership_id"	text,
	"check_in_date"	integer,
	"check_in_time"	integer,
	"check_out_time"	integer,
	FOREIGN KEY("membership_id") REFERENCES "get_fit_now_member"("id")
);
CREATE TABLE IF NOT EXISTS "solution" (
	"user"	integer,
	"value"	text
);
CREATE TABLE IF NOT EXISTS "income" (
	"ssn"	CHAR,
	"annual_income"	integer,
	PRIMARY KEY("ssn")
);
CREATE TABLE IF NOT EXISTS "person" (
	"id"	integer,
	"name"	text,
	"license_id"	integer,
	"address_number"	integer,
	"address_street_name"	text,
	"ssn"	CHAR,
	PRIMARY KEY("id"),
	FOREIGN KEY("ssn") REFERENCES "income"("ssn"),
	FOREIGN KEY("license_id") REFERENCES "driver_license"("id")
);
CREATE TRIGGER check_solution AFTER INSERT ON solution
    WHEN new.user==1
    BEGIN
        DELETE FROM solution;
        CASE WHEN new.value=='Jeremy Bowers' THEN 'Bravo, vous avez trouvé le meurtrier ! Mais ce n''est pas fini : ce n''est pas lui qui a commandité le crime. Allez lire sa déposition dans la table interview pour remonter jusqu''au cerveau de l''affaire.'
             WHEN new.value=='Miranda Priestly' THEN 'Bravo, vous avez trouvé le cerveau de l''affaire ! Tout SQL City vous salue comme le plus grand détective SQL de tous les temps.'
             ELSE 'Ce n''est pas la bonne personne. Essayez encore !'
        END
        );
    END;
COMMIT;
